1	import { StateEffect } from '@codemirror/state';
2	
3	export interface CodeBlockSourceModeToggle {
4	  from: number;
5	  to: number;
6	  showSource: boolean;
7	}
8	
9	export const setCodeBlockSourceMode =
10	  StateEffect.define<CodeBlockSourceModeToggle>();
11

1	/**
2	 * Code Block Widget
3	 *
4	 * Renders syntax-highlighted code blocks with copy button and line numbers
5	 * Supports precise click position mapping
6	 */
7	
8	import { EditorView, WidgetType } from '@codemirror/view';
9	import { highlightCode } from '../utils/codeHighlight';
10	import { setCodeBlockSourceMode } from '../plugins/codeBlockEffects';
11	
12	/**
13	 * Code block data interface
14	 */
15	export interface CodeBlockData {
16	  /** Source code */
17	  code: string;
18	  /** Language identifier */
19	  language: string;
20	  /** Whether to show line numbers */
21	  showLineNumbers: boolean;
22	  /** Whether to show copy button */
23	  showCopyButton: boolean;
24	  /** Whether to show source toggle button */
25	  showSourceToggle?: boolean;
26	  /** Code block start position in document */
27	  from: number;
28	  /** Code block end position in document */
29	  to: number;
30	  /** Code content start position (after ```language) */
31	  codeFrom: number;
32	  /** Start position of each line (relative to document) */
33	  lineStarts: number[];
34	}
35	
36	/**
37	 * Code Block Widget class
38	 */
39	export class CodeBlockWidget extends WidgetType {
40	  constructor(readonly data: CodeBlockData) {
41	    super();
42	  }
43	
44	  /**
45	   * Check if two widgets are equal
46	   */
47	  eq(other: CodeBlockWidget): boolean {
48	    return (
49	      other.data.code === this.data.code &&
50	      other.data.language === this.data.language &&
51	      other.data.showLineNumbers === this.data.showLineNumbers &&
52	      other.data.showCopyButton === this.data.showCopyButton &&
53	      other.data.showSourceToggle === this.data.showSourceToggle &&
54	      other.data.from === this.data.from
55	    );
56	  }
57	
58	  /**
59	   * Render to DOM element
60	   */
61	  toDOM(view?: EditorView): HTMLElement {
62	    const {
63	      code,
64	      language,
65	      showLineNumbers,
66	      showCopyButton,
67	      showSourceToggle = false,
68	      from,
69	      lineStarts,
70	    } = this.data;
71	    const widgetData = this.data;
72	
73	    // Container
74	    const container = document.createElement('div');
75	    container.className = 'cm-codeblock-widget';
76	    container.dataset.from = String(from);
77	    container.dataset.to = String(this.data.to);
78	    container.dataset.lineStarts = JSON.stringify(lineStarts);
79	
80	    if (showLineNumbers) {
81	      container.className += ' cm-codeblock-line-numbers';
82	    }
83	
84	    if (showSourceToggle) {
85	      const stopBubbleForBody = (event: Event) => {
86	        const target = event.target as HTMLElement | null;
87	        if (target?.closest('.cm-codeblock-copy, .cm-codeblock-toggle')) {
88	          return;
89	        }
90	        // Prevent editor-level pointer handlers from firing while
91	        // keeping native text selection intact.
92	        event.stopPropagation();
93	      };
94	
95	      container.addEventListener('mousedown', stopBubbleForBody, true);
96	      container.addEventListener('mouseup', stopBubbleForBody, true);
97	      container.addEventListener('click', stopBubbleForBody, true);
98	    }
99	
100	    const enableClickToEdit = !showSourceToggle;
101	
102	    // Auto mode: click rendered block to jump to source position.
103	    if (enableClickToEdit && view) {
104	      container.addEventListener(
105	        'mousedown',
106	        (event) => {
107	          const target = event.target as HTMLElement;
108	
109	          // Don't handle toolbar buttons
110	          if (target.closest('.cm-codeblock-copy, .cm-codeblock-toggle')) {
111	            return;
112	          }
113	
114	          event.stopPropagation();
115	          event.preventDefault();
116	
117	          // Find clicked line
118	          const lineEl = target.closest('.cm-codeblock-line');
119	          let targetPos = widgetData.from;
120	
121	          if (lineEl) {
122	            const lineIndex = parseInt(
123	              (lineEl as HTMLElement).dataset.lineIndex || '0',
124	              10
125	            );
126	
127	            if (lineIndex === -1) {
128	              targetPos = widgetData.from;
129	            } else if (lineIndex === -2) {
130	              targetPos = widgetData.to;
131	            } else if (
132	              lineIndex >= 0 &&
133	              lineIndex < widgetData.lineStarts.length
134	            ) {
135	              targetPos = widgetData.lineStarts[lineIndex];
136	
137	              // Calculate column position using precise measurement
138	              const charOffset = this.measureClickOffset(
139	                lineEl as HTMLElement,
140	                event.clientX,
141	                widgetData.code.split('\n')[lineIndex] || ''
142	              );
143	              targetPos += charOffset;
144	            }
145	          }
146	
147	          view.dispatch({
148	            selection: { anchor: targetPos },
149	            scrollIntoView: true,
150	          });
151	          view.focus();
152	        },
153	        true
154	      );
155	    }
156	
157	    const toolbar = document.createElement('div');
158	    toolbar.className = 'cm-codeblock-actions';
159	
160	    if (showSourceToggle) {
161	      const toggleBtn = document.createElement('button');
162	      toggleBtn.type = 'button';
163	      toggleBtn.className = 'cm-codeblock-toggle';
164	      toggleBtn.textContent = 'MD';
165	      toggleBtn.setAttribute('aria-label', 'Show markdown source');
166	      toggleBtn.addEventListener('click', (event) => {
167	        event.preventDefault();
168	        event.stopPropagation();
169	        if (!view) return;
170	        view.dispatch({
171	          selection: { anchor: widgetData.from },
172	          effects: setCodeBlockSourceMode.of({
173	            from: widgetData.from,
174	            to: widgetData.to,
175	            showSource: true,
176	          }),
177	          scrollIntoView: true,
178	        });
179	        view.focus();
180	      });
181	      toolbar.appendChild(toggleBtn);
182	    }
183	
184	    // Copy button
185	    if (showCopyButton) {
186	      const copyBtn = document.createElement('button');
187	      copyBtn.type = 'button';
188	      copyBtn.className = 'cm-codeblock-copy';
189	      copyBtn.textContent = 'Copy';
190	      copyBtn.setAttribute('aria-label', 'Copy code');
191	
192	      copyBtn.addEventListener('click', async (e) => {
193	        e.preventDefault();
194	        e.stopPropagation();
195	
196	        try {
197	          const copied = await this.copyText(code);
198	          if (!copied) {
199	            throw new Error('Copy failed');
200	          }
201	          copyBtn.textContent = 'Copied!';
202	          copyBtn.classList.add('cm-codeblock-copy-success');
203	
204	          setTimeout(() => {
205	            copyBtn.textContent = 'Copy';
206	            copyBtn.classList.remove('cm-codeblock-copy-success');
207	          }, 2000);
208	        } catch {
209	          copyBtn.textContent = 'Failed';
210	          setTimeout(() => {
211	            copyBtn.textContent = 'Copy';
212	          }, 2000);
213	        }
214	      });
215	
216	      toolbar.appendChild(copyBtn);
217	    }
218	
219	    if (toolbar.childElementCount > 0) {
220	      container.appendChild(toolbar);
221	    }
222	
223	    // Code area
224	    const pre = document.createElement('pre');
225	    const codeEl = document.createElement('code');
226	
227	    // Start fence line
228	    const openFence = `\`\`\`${language || ''}`;
229	
230	    // Split original code by lines to ensure line count matches lineStarts
231	    const originalLines = code.split('\n');
232	
233	    // Highlight entire code block
234	    const result = highlightCode(code, language || undefined);
235	    const highlightedHtml = result.html;
236	
237	    // Try to split highlighted HTML by newlines
238	    // If line count doesn't match, highlight each line separately
239	    let highlightedLines = highlightedHtml.split('\n');
240	
241	    if (highlightedLines.length !== originalLines.length) {
242	      // Line count mismatch, highlight each line separately
243	      highlightedLines = originalLines.map((line) => {
244	        const lineResult = highlightCode(line, language || undefined);
245	        return lineResult.html || this.escapeHtml(line) || ' ';
246	      });
247	    }
248	
249	    // Build all lines: fence + code + fence
250	    const allLines: string[] = [];
251	
252	    // Start fence (index -1 indicates fence line)
253	    allLines.push(
254	      `<span class="cm-codeblock-line cm-codeblock-fence" data-line-index="-1">${this.escapeHtml(openFence)}</span>`
255	    );
256	
257	    // Code lines - use original line count
258	    originalLines.forEach((_, index) => {
259	      const lineHtml = highlightedLines[index] || ' ';
260	      allLines.push(
261	        `<span class="cm-codeblock-line" data-line-index="${index}">${lineHtml || ' '}</span>`
262	      );
263	    });
264	
265	    // End fence (index -2 indicates end fence)
266	    allLines.push(
267	      `<span class="cm-codeblock-line cm-codeblock-fence" data-line-index="-2">\`\`\`</span>`
268	    );
269	
270	    codeEl.innerHTML = allLines.join('');
271	
272	    pre.appendChild(codeEl);
273	    container.appendChild(pre);
274	
275	    return container;
276	  }
277	
278	  /**
279	   * HTML escape
280	   */
281	  private escapeHtml(text: string): string {
282	    return text
283	      .replace(/&/g, '&amp;')
284	      .replace(/</g, '&lt;')
285	      .replace(/>/g, '&gt;');
286	  }
287	
288	  /**
289	   * Precisely measure click position to character offset
290	   *
291	   * Uses Canvas to measure text width and find character at click position
292	   *
293	   * @param lineEl - Line element
294	   * @param clientX - Click X coordinate
295	   * @param sourceText - Source line text (to limit max offset)
296	   * @returns Character offset
297	   */
298	  private measureClickOffset(
299	    lineEl: HTMLElement,
300	    clientX: number,
301	    sourceText: string
302	  ): number {
303	    const rect = lineEl.getBoundingClientRect();
304	    const clickX = clientX - rect.left;
305	
306	    // Get line padding
307	    const style = window.getComputedStyle(lineEl);
308	    const paddingLeft = parseFloat(style.paddingLeft) || 0;
309	
310	    // Adjust click position by subtracting padding
311	    const textClickX = clickX - paddingLeft;
312	
313	    if (textClickX <= 0) {
314	      return 0;
315	    }
316	
317	    // Use Canvas to measure text width
318	    const canvas = document.createElement('canvas');
319	    const ctx = canvas.getContext('2d');
320	
321	    if (!ctx) {
322	      // Fallback: use simple estimation
323	      const fontSize = parseFloat(style.fontSize) || 16;
324	      const charWidth = fontSize * 0.6;
325	      const charOffset = Math.floor(textClickX / charWidth);
326	      return Math.min(charOffset, sourceText.length);
327	    }
328	
329	    // Set same font as line element
330	    ctx.font = `${style.fontSize} ${style.fontFamily}`;
331	
332	    // Binary search for character at click position
333	    // Use source text for measurement to ensure consistency with source position
334	    const text = sourceText;
335	    let left = 0;
336	    let right = text.length;
337	
338	    while (left < right) {
339	      const mid = Math.floor((left + right + 1) / 2);
340	      const width = ctx.measureText(text.substring(0, mid)).width;
341	
342	      if (width <= textClickX) {
343	        left = mid;
344	      } else {
345	        right = mid - 1;
346	      }
347	    }
348	
349	    // Check if closer to next character
350	    if (left < text.length) {
351	      const currentWidth = ctx.measureText(text.substring(0, left)).width;
352	      const nextWidth = ctx.measureText(text.substring(0, left + 1)).width;
353	      const midPoint = (currentWidth + nextWidth) / 2;
354	
355	      if (textClickX > midPoint) {
356	        left++;
357	      }
358	    }
359	
360	    return Math.min(left, sourceText.length);
361	  }
362	
363	  private async copyText(text: string): Promise<boolean> {
364	    const clipboard = navigator.clipboard;
365	
366	    if (clipboard?.writeText) {
367	      try {
368	        await clipboard.writeText(text);
369	        return true;
370	      } catch {
371	        // Fall back to execCommand in environments without clipboard permission.
372	      }
373	    }
374	
375	    return this.fallbackCopyWithExecCommand(text);
376	  }
377	
378	  private fallbackCopyWithExecCommand(text: string): boolean {
379	    if (typeof document.execCommand !== 'function') {
380	      return false;
381	    }
382	
383	    const textarea = document.createElement('textarea');
384	    textarea.value = text;
385	    textarea.setAttribute('readonly', 'true');
386	    textarea.style.position = 'fixed';
387	    textarea.style.top = '-9999px';
388	    textarea.style.left = '-9999px';
389	    document.body.appendChild(textarea);
390	
391	    const selection = document.getSelection();
392	    const previousRanges: Range[] = [];
393	    if (selection) {
394	      for (let i = 0; i < selection.rangeCount; i++) {
395	        previousRanges.push(selection.getRangeAt(i));
396	      }
397	    }
398	
399	    textarea.focus();
400	    textarea.select();
401	    textarea.setSelectionRange(0, textarea.value.length);
402	
403	    let copied = false;
404	    try {
405	      copied = document.execCommand('copy');
406	    } catch {
407	      copied = false;
408	    }
409	
410	    document.body.removeChild(textarea);
411	
412	    if (selection) {
413	      selection.removeAllRanges();
414	      previousRanges.forEach((range) => selection.addRange(range));
415	    }
416	
417	    return copied;
418	  }
419	
420	  /**
421	   * Whether to ignore events
422	   *
423	   * Return true for mousedown to prevent CodeMirror default handling
424	   * We handle clicks ourselves in codeBlock.ts with domEventHandlers
425	   */
426	  ignoreEvent(event: Event): boolean {
427	    if (this.data.showSourceToggle) {
428	      const mouseEvents = new Set([
429	        'mousedown',
430	        'mouseup',
431	        'mousemove',
432	        'click',
433	        'dblclick',
434	        'contextmenu',
435	      ]);
436	      if (mouseEvents.has(event.type)) {
437	        return true;
438	      }
439	    }
440	
441	    if (event.type === 'mousedown') {
442	      const target = event.target as HTMLElement | null;
443	
444	      if (target?.closest('.cm-codeblock-copy')) {
445	        return true;
446	      }
447	      return true;
448	    }
449	    return false;
450	  }
451	}
