1	/**
2	 * Code Highlighting Utility
3	 *
4	 * Wraps lowlight to provide syntax highlighting functionality
5	 * Supports on-demand language loading with graceful degradation
6	 */
7	
8	import type { LanguageFn } from 'highlight.js';
9	
10	/**
11	 * Highlight result interface
12	 */
13	export interface HighlightResult {
14	  /** Highlighted HTML string */
15	  html: string;
16	  /** Language identifier */
17	  language: string;
18	  /** Whether the language was auto-detected */
19	  detected: boolean;
20	}
21	
22	// lowlight instance (lazy initialization)
23	let lowlightInstance: any = null;
24	let lowlightAvailable: boolean | null = null;
25	
26	/**
27	 * Escape HTML special characters
28	 */
29	function escapeHtml(text: string): string {
30	  return text
31	    .replace(/&/g, '&amp;')
32	    .replace(/</g, '&lt;')
33	    .replace(/>/g, '&gt;')
34	    .replace(/"/g, '&quot;')
35	    .replace(/'/g, '&#039;');
36	}
37	
38	/**
39	 * Convert HAST node to HTML string
40	 */
41	function hastToHtml(node: any): string {
42	  if (!node) return '';
43	
44	  if (node.type === 'text') {
45	    return escapeHtml(node.value || '');
46	  }
47	
48	  if (node.type === 'element') {
49	    const tag = node.tagName;
50	    const classes = node.properties?.className?.join(' ') || '';
51	    const classAttr = classes ? ` class="${classes}"` : '';
52	    const children = (node.children || []).map(hastToHtml).join('');
53	    return `<${tag}${classAttr}>${children}</${tag}>`;
54	  }
55	
56	  if (node.type === 'root') {
57	    return (node.children || []).map(hastToHtml).join('');
58	  }
59	
60	  return '';
61	}
62	
63	// Cached lowlight module
64	let lowlightModule: { createLowlight: any; common: any } | null = null;
65	
66	// Try to load lowlight module
67	async function loadLowlightModule(): Promise<boolean> {
68	  if (lowlightModule !== null) {
69	    return true;
70	  }
71	  try {
72	    // Dynamic import for ESM module
73	    const mod = await import('lowlight');
74	    lowlightModule = mod;
75	    return true;
76	  } catch {
77	    return false;
78	  }
79	}
80	
81	// Synchronous initialization (for tests and first call)
82	function initLowlightSync(): boolean {
83	  if (lowlightAvailable !== null) {
84	    return lowlightAvailable;
85	  }
86	
87	  // If module is already loaded, use it
88	  if (lowlightModule) {
89	    try {
90	      lowlightInstance = lowlightModule.createLowlight(lowlightModule.common);
91	      lowlightAvailable = true;
92	      return true;
93	    } catch {
94	      lowlightAvailable = false;
95	      return false;
96	    }
97	  }
98	
99	  // Try synchronous require (may work in some environments)
100	  try {
101	    // eslint-disable-next-line @typescript-eslint/no-var-requires
102	    const { createLowlight, common } = require('lowlight');
103	    lowlightInstance = createLowlight(common);
104	    lowlightAvailable = true;
105	    return true;
106	  } catch {
107	    // If sync loading fails, mark as unavailable
108	    // Async loading will try in background
109	    lowlightAvailable = false;
110	    return false;
111	  }
112	}
113	
114	// Async initialization (recommended)
115	async function initLowlightAsync(): Promise<boolean> {
116	  if (lowlightAvailable === true && lowlightInstance) {
117	    return true;
118	  }
119	
120	  const loaded = await loadLowlightModule();
121	  if (!loaded || !lowlightModule) {
122	    lowlightAvailable = false;
123	    return false;
124	  }
125	
126	  try {
127	    lowlightInstance = lowlightModule.createLowlight(lowlightModule.common);
128	    lowlightAvailable = true;
129	    return true;
130	  } catch {
131	    lowlightAvailable = false;
132	    return false;
133	  }
134	}
135	
136	/**
137	 * Reset highlighter (for testing)
138	 */
139	export function resetHighlighter(): void {
140	  lowlightInstance = null;
141	  lowlightAvailable = null;
142	  // Don't auto-initialize, let tests control initialization timing
143	}
144	
145	/**
146	 * Initialize highlighter asynchronously
147	 * Recommended to call at application startup
148	 */
149	export async function initHighlighter(): Promise<boolean> {
150	  return initLowlightAsync();
151	}
152	
153	/**
154	 * Check if highlighter is available
155	 */
156	export function isHighlighterAvailable(): boolean {
157	  return lowlightAvailable === true && lowlightInstance !== null;
158	}
159	
160	/**
161	 * Highlight code
162	 *
163	 * @param code - Source code
164	 * @param lang - Language identifier (optional, auto-detect if not provided)
165	 * @returns Highlight result
166	 */
167	export function highlightCode(code: string, lang?: string): HighlightResult {
168	  // Return early for empty code
169	  if (!code) {
170	    return {
171	      html: '',
172	      language: lang || 'text',
173	      detected: false,
174	    };
175	  }
176	
177	  // Ensure lowlight is initialized
178	  if (!initLowlightSync()) {
179	    // lowlight not available, return escaped plain text
180	    return {
181	      html: escapeHtml(code),
182	      language: lang || 'text',
183	      detected: false,
184	    };
185	  }
186	
187	  try {
188	    if (lang) {
189	      // Specified language
190	      if (lowlightInstance.registered(lang)) {
191	        const result = lowlightInstance.highlight(lang, code);
192	        return {
193	          html: hastToHtml(result),
194	          language: lang,
195	          detected: false,
196	        };
197	      } else {
198	        // Language not registered, return plain text
199	        return {
200	          html: escapeHtml(code),
201	          language: lang,
202	          detected: false,
203	        };
204	      }
205	    } else {
206	      // Auto-detect language
207	      const result = lowlightInstance.highlightAuto(code);
208	      return {
209	        html: hastToHtml(result),
210	        language: result.data?.language || 'text',
211	        detected: true,
212	      };
213	    }
214	  } catch {
215	    // Highlighting failed, return plain text
216	    return {
217	      html: escapeHtml(code),
218	      language: lang || 'text',
219	      detected: false,
220	    };
221	  }
222	}
223	
224	/**
225	 * Register a language
226	 *
227	 * @param name - Language name
228	 * @param syntax - Language definition function
229	 */
230	export function registerLanguage(name: string, syntax: LanguageFn): void {
231	  if (!initLowlightSync()) {
232	    console.warn('[codeHighlight] lowlight not available, cannot register language');
233	    return;
234	  }
235	
236	  try {
237	    lowlightInstance.register({ [name]: syntax });
238	  } catch (error) {
239	    console.warn(`[codeHighlight] Failed to register language "${name}":`, error);
240	  }
241	}
242	
243	/**
244	 * Highlight code and return raw HAST tree (for mark decorations)
245	 *
246	 * @param code - Source code
247	 * @param lang - Language identifier
248	 * @returns HAST root node, or null if highlighting unavailable
249	 */
250	export function highlightCodeHast(code: string, lang?: string): any | null {
251	  if (!code) return null;
252	  if (!initLowlightSync()) return null;
253	
254	  try {
255	    if (lang && lowlightInstance.registered(lang)) {
256	      return lowlightInstance.highlight(lang, code);
257	    }
258	    if (!lang) {
259	      return lowlightInstance.highlightAuto(code);
260	    }
261	    return null;
262	  } catch {
263	    return null;
264	  }
265	}
266	
267	/**
268	 * Check if a language is registered
269	 *
270	 * @param name - Language name
271	 * @returns Whether the language is registered
272	 */
273	export function isLanguageRegistered(name: string): boolean {
274	  if (!initLowlightSync()) {
275	    return false;
