function createCodeBlockField(options: Required<CodeBlockOptions>): StateField<DecorationSet> {
  const isInline = options.interaction === 'inline';
  const buildFn = isInline ? buildCodeBlockInlineDecorations : buildCodeBlockDecorations;

  return StateField.define<DecorationSet>({
    create(state) {
      return buildFn(state, options);
    },

    update(deco, tr) {
      // Rebuild on document change, reconfiguration, or source mode toggle
      if (
        tr.docChanged ||
        tr.reconfigured ||
        tr.effects.some((effect) => effect.is(setCodeBlockSourceMode))
      ) {
        return buildFn(tr.state, options);
      }

      // Inline and toggle modes: don't rebuild on selection change
      if (options.interaction !== 'auto') {
        return deco;
      }

      // Auto mode: rebuild on drag state change and selection change
      // ... (drag handling code shown above)
      if (tr.selection) {
        return buildFn(tr.state, options);
      }

      return deco;
    },

    provide: (f) => EditorView.decorations.from(f),
  });
}
