## 6. CODEHIGHLIGHT (Lowlight Integration)

### 6.1 Lazy Initialization (Lines 67-134)

```typescript
// Cached lowlight module
let lowlightModule: { createLowlight: any; common: any } | null = null;
let lowlightInstance: any = null;
let lowlightAvailable: boolean | null = null;

async function loadLowlightModule(): Promise<boolean> {
  if (lowlightModule !== null) return true;
  try {
    const mod = await import('lowlight');
    lowlightModule = mod;
    return true;
  } catch {
    return false;
  }
}

// Synchronous initialization
function initLowlightSync(): boolean {
  if (lowlightAvailable !== null) return lowlightAvailable;

  if (lowlightModule) {
    try {
      lowlightInstance = lowlightModule.createLowlight(lowlightModule.common);
      lowlightAvailable = true;
      return true;
    } catch {
      lowlightAvailable = false;
      return false;
    }
  }

  try {
    const { createLowlight, common } = require('lowlight');
    lowlightInstance = createLowlight(common);
    lowlightAvailable = true;
    return true;
  } catch {
    lowlightAvailable = false;
    return false;
  }
}

// Async initialization (recommended)
export async function initHighlighter(): Promise<boolean> {
  return initLowlightAsync();
}
```

### 6.2 highlightCode vs highlightCodeHast (Lines 167-265)

**`highlightCode` - returns HTML string (lines 167-222):**
```typescript
export function highlightCode(code: string, lang?: string): HighlightResult {
  if (!code) {
    return { html: '', language: lang || 'text', detected: false };
  }

  if (!initLowlightSync()) {
    // Graceful degradation: return escaped plain text
    return { html: escapeHtml(code), language: lang || 'text', detected: false };
  }

  try {
    if (lang) {
      if (lowlightInstance.registered(lang)) {
        const result = lowlightInstance.highlight(lang, code);
        return {
          html: hastToHtml(result),
          language: lang,
          detected: false,
        };
      } else {
        // Language not registered, return plain text
        return { html: escapeHtml(code), language: lang, detected: false };
      }
    } else {
      // Auto-detect language
      const result = lowlightInstance.highlightAuto(code);
      return {
        html: hastToHtml(result),
        language: result.data?.language || 'text',
        detected: true,
      };
    }
  } catch {
    return { html: escapeHtml(code), language: lang || 'text', detected: false };
  }
}
```

**`highlightCodeHast` - returns raw HAST tree (lines 250-265):**
```typescript
export function highlightCodeHast(code: string, lang?: string): any | null {
  if (!code) return null;
  if (!initLowlightSync()) return null;

  try {
    if (lang && lowlightInstance.registered(lang)) {
      return lowlightInstance.highlight(lang, code);
    }
    if (!lang) {
      return lowlightInstance.highlightAuto(code);
    }
    return null;
  } catch {
    return null;
  }
}
```

### 6.3 HAST to Mark Decorations (codeBlock.ts lines 254-286)

For inline mode, HAST is converted to mark decorations:

```typescript
interface HastNode {
  type: string;
  value?: string;
  tagName?: string;
  properties?: { className?: string[] };
  children?: HastNode[];
}

function hastToMarkDecorations(root: HastNode, basePos: number): Range<Decoration>[] {
  const result: Range<Decoration>[] = [];
  let offset = 0;

  function walk(node: HastNode, cls?: string) {
    if (node.type === 'text') {
      const len = node.value?.length || 0;
      if (cls && len > 0) {
        result.push(
          Decoration.mark({ class: cls }).range(
            basePos + offset,
            basePos + offset + len
          )
        );
      }
      offset += len;
    } else if (node.type === 'element' || node.type === 'root') {
      const nodeClass = node.properties?.className?.join(' ');
      const effectiveClass = nodeClass || cls;
      if (node.children) {
        for (const child of node.children) {
          walk(child, effectiveClass);
        }
      }
    }
  }

  walk(root);
  return result;
}
```

